package com.example.product;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController public class ProductController{private final JdbcTemplate jdbc; public ProductController(JdbcTemplate jdbc){this.jdbc=jdbc;} @GetMapping("/api/products") public List<java.util.Map<String,Object>> products(){return jdbc.queryForList("select id,name,price,stock from product where is_on_sale=1 order by id");} @GetMapping("/api/categories") public List<java.util.Map<String,Object>> categories(){return jdbc.queryForList("select * from product_category order by sort_order,id");} @GetMapping("/api/marketing/promotions") public List<java.util.Map<String,Object>> promotions(){return jdbc.queryForList("select * from promotion where enabled=1 and now() between start_at and end_at");}}